<?php $logoData=$asset($logo); ?>
<!doctype html><html><head><meta charset="UTF-8"><title><?= $escape($title) ?></title><style>
@page{margin:25px 28px 35px}body{font-family:DejaVu Sans,Arial,sans-serif;color:#243040;font-size:10px}.top{padding:14px 16px;background:#26364a;color:#fff;border-radius:6px;margin-bottom:16px}.top img{max-height:45px;max-width:130px;vertical-align:middle;margin-right:12px}.title{font-size:20px;font-weight:bold}.meta{font-size:8px;opacity:.8;margin-top:5px}table{width:100%;border-collapse:separate;border-spacing:0;overflow:hidden;border:1px solid #d8dee6;border-radius:6px}thead{display:table-header-group}th{background:#eef2f6;padding:8px;border-bottom:2px solid #c8d0da;text-align:left}td{padding:7px;border-bottom:1px solid #e4e8ed}tr:last-child td{border-bottom:0}.group-row td{background:#dfe7f0;font-weight:bold;border-bottom:1px solid #c5cfda}.group-total td{font-weight:bold;background:#f6f8fa}.summary{margin-top:14px;padding:12px;background:#f6f8fa;border:1px solid #dce2e8;border-radius:6px}.footer{margin-top:16px;color:#65717f;font-size:8px;border-top:1px solid #dce2e8;padding-top:8px}</style></head><body>
<div class="top"><?php if($logoData): ?><img src="<?= $escape($logoData) ?>"><?php endif; ?><span class="title"><?= $escape($title) ?></span><?php if($header): ?><div><?= nl2br($escape($header)) ?></div><?php endif; ?><?php if($showGeneratedMeta): ?><div class="meta">Generated <?= $escape($generated) ?> by <?= $escape($generatedBy) ?></div><?php endif; ?></div>
<table><thead><tr><?php foreach($columns as $c): ?><th style="text-align:<?= $escape($c['align']??'left') ?>"><?= $escape($c['label']) ?></th><?php endforeach; ?></tr></thead><tbody><?php if($hasGrouping): foreach($groups as $g): ?><tr class="group-row"><td colspan="<?= count($columns) ?>"><?= $escape($g['key']) ?></td></tr><?php foreach($g['rows'] as $r): ?><tr><?php foreach($columns as $c): ?><td style="text-align:<?= $escape($c['align']??'left') ?>"><?= $escape($format($value($r,$c['key']),$c)) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if($g['calculations']): ?><tr class="group-total"><td colspan="<?= count($columns)-1 ?>">Group totals</td><td><?= $escape(json_encode($g['calculations'],JSON_UNESCAPED_UNICODE)) ?></td></tr><?php endif; ?><?php endforeach; else: foreach($rows as $r): ?><tr><?php foreach($columns as $c): ?><td style="text-align:<?= $escape($c['align']??'left') ?>"><?= $escape($format($value($r,$c['key']),$c)) ?></td><?php endforeach; ?></tr><?php endforeach; endif; ?></tbody></table>
<?php if($summary||$calculations): ?><div class="summary"><strong>Summary</strong><?php foreach($summary as $k=>$v): ?><div><?= $escape($k) ?>: <?= $escape($v) ?></div><?php endforeach; ?><?php foreach($calculations as $k=>$v): ?><div><?= $escape($k) ?>: <?= $escape($v) ?></div><?php endforeach; ?></div><?php endif; ?><?php if($footer): ?><div class="footer"><?= nl2br($escape($footer)) ?></div><?php endif; ?></body></html>
